41	/**
42	 * A specification of a {@link CacheBuilder} configuration.
43	 *
44	 * <p>{@code CacheBuilderSpec} supports parsing configuration off of a string, which makes it
45	 * especially useful for command-line configuration of a {@code CacheBuilder}.
46	 *
47	 * <p>The string syntax is a series of comma-separated keys or key-value pairs, each corresponding
48	 * to a {@code CacheBuilder} method.
49	 *
50	 * <ul>
51	 *   <li>{@code concurrencyLevel=[integer]}: sets {@link CacheBuilder#concurrencyLevel}.
52	 *   <li>{@code initialCapacity=[integer]}: sets {@link CacheBuilder#initialCapacity}.
53	 *   <li>{@code maximumSize=[long]}: sets {@link CacheBuilder#maximumSize}.
54	 *   <li>{@code maximumWeight=[long]}: sets {@link CacheBuilder#maximumWeight}.
55	 *   <li>{@code expireAfterAccess=[duration]}: sets {@link CacheBuilder#expireAfterAccess}.
56	 *   <li>{@code expireAfterWrite=[duration]}: sets {@link CacheBuilder#expireAfterWrite}.
57	 *   <li>{@code refreshAfterWrite=[duration]}: sets {@link CacheBuilder#refreshAfterWrite}.
58	 *   <li>{@code weakKeys}: sets {@link CacheBuilder#weakKeys}.
59	 *   <li>{@code softValues}: sets {@link CacheBuilder#softValues}.
60	 *   <li>{@code weakValues}: sets {@link CacheBuilder#weakValues}.
61	 *   <li>{@code recordStats}: sets {@link CacheBuilder#recordStats}.
62	 * </ul>
63	 *
64	 * <p>The set of supported keys will grow as {@code CacheBuilder} evolves, but existing keys will
65	 * never be removed.
66	 *
67	 * <p>Durations are represented by an integer, followed by one of "d", "h", "m", or "s",
68	 * representing days, hours, minutes, or seconds respectively. (There is currently no syntax to
69	 * request expiration in milliseconds, microseconds, or nanoseconds.)
70	 *
71	 * <p>Whitespace before and after commas and equal signs is ignored. Keys may not be repeated; it is
72	 * also illegal to use the following pairs of keys in a single value:
73	 *
74	 * <ul>
75	 *   <li>{@code maximumSize} and {@code maximumWeight}
76	 *   <li>{@code softValues} and {@code weakValues}
77	 * </ul>
78	 *
79	 * <p>{@code CacheBuilderSpec} does not support configuring {@code CacheBuilder} methods with
80	 * non-value parameters. These must be configured in code.
81	 *
82	 * <p>A new {@code CacheBuilder} can be instantiated from a {@code CacheBuilderSpec} using {@link
83	 * CacheBuilder#from(CacheBuilderSpec)} or {@link CacheBuilder#from(String)}.
84	 *
85	 * @author Adam Winer
86	 * @since 12.0
87	 */
88	@SuppressWarnings("GoodTime") // lots of violations (nanosecond math)
89	@GwtIncompatible
90	@J2ktIncompatible
91	public final class CacheBuilderSpec {
92	  /** Parses a single value. */
93	  private interface ValueParser {
94	    void parse(CacheBuilderSpec spec, String key, @Nullable String value);
95	  }
96	
97	  /** Splits each key-value pair. */
98	  private static final Splitter KEYS_SPLITTER = Splitter.on(',').trimResults();
99	
100	  /** Splits the key from the value. */
101	  private static final Splitter KEY_VALUE_SPLITTER = Splitter.on('=').trimResults();
102	
103	  /** Map of names to ValueParser. */
104	  private static final ImmutableMap<String, ValueParser> VALUE_PARSERS =
105	      ImmutableMap.<String, ValueParser>builder()
106	          .put("initialCapacity", new InitialCapacityParser())
107	          .put("maximumSize", new MaximumSizeParser())
108	          .put("maximumWeight", new MaximumWeightParser())
109	          .put("concurrencyLevel", new ConcurrencyLevelParser())
110	          .put("weakKeys", new KeyStrengthParser(Strength.WEAK))
111	          .put("softValues", new ValueStrengthParser(Strength.SOFT))
112	          .put("weakValues", new ValueStrengthParser(Strength.WEAK))
113	          .put("recordStats", new RecordStatsParser())
114	          .put("expireAfterAccess", new AccessDurationParser())
115	          .put("expireAfterWrite", new WriteDurationParser())
116	          .put("refreshAfterWrite", new RefreshDurationParser())
117	          .put("refreshInterval", new RefreshDurationParser())
118	          .buildOrThrow();
119	
120	  @VisibleForTesting @Nullable Integer initialCapacity;
121	  @VisibleForTesting @Nullable Long maximumSize;
122	  @VisibleForTesting @Nullable Long maximumWeight;
123	  @VisibleForTesting @Nullable Integer concurrencyLevel;
124	  @VisibleForTesting @Nullable Strength keyStrength;
125	  @VisibleForTesting @Nullable Strength valueStrength;
126	  @VisibleForTesting @Nullable Boolean recordStats;
127	  @VisibleForTesting long writeExpirationDuration;
128	  @VisibleForTesting @Nullable TimeUnit writeExpirationTimeUnit;
129	  @VisibleForTesting long accessExpirationDuration;
130	  @VisibleForTesting @Nullable TimeUnit accessExpirationTimeUnit;
131	  @VisibleForTesting long refreshDuration;
132	  @VisibleForTesting @Nullable TimeUnit refreshTimeUnit;
133	
134	  /** Specification; used for toParseableString(). */
135	  private final String specification;
136	
137	  private CacheBuilderSpec(String specification) {
138	    this.specification = specification;
139	  }
140	
141	  /**
142	   * Creates a CacheBuilderSpec from a string.
143	   *
144	   * @param cacheBuilderSpecification the string form
145	   */
146	  public static CacheBuilderSpec parse(String cacheBuilderSpecification) {
147	    CacheBuilderSpec spec = new CacheBuilderSpec(cacheBuilderSpecification);
148	    if (!cacheBuilderSpecification.isEmpty()) {
149	      for (String keyValuePair : KEYS_SPLITTER.split(cacheBuilderSpecification)) {
150	        List<String> keyAndValue = ImmutableList.copyOf(KEY_VALUE_SPLITTER.split(keyValuePair));
151	        checkArgument(!keyAndValue.isEmpty(), "blank key-value pair");
152	        checkArgument(
153	            keyAndValue.size() <= 2,
154	            "key-value pair %s with more than one equals sign",
155	            keyValuePair);
156	
157	        // Find the ValueParser for the current key.
158	        String key = keyAndValue.get(0);
159	        ValueParser valueParser = VALUE_PARSERS.get(key);
160	        checkArgument(valueParser != null, "unknown key %s", key);
161	
162	        String value = keyAndValue.size() == 1 ? null : keyAndValue.get(1);
163	        valueParser.parse(spec, key, value);
164	      }
165	    }
166	
167	    return spec;
168	  }
