176	  /** Returns a CacheBuilder configured according to this instance's specification. */
177	  CacheBuilder<Object, Object> toCacheBuilder() {
178	    CacheBuilder<Object, Object> builder = CacheBuilder.newBuilder();
179	    if (initialCapacity != null) {
180	      builder.initialCapacity(initialCapacity);
181	    }
182	    if (maximumSize != null) {
183	      builder.maximumSize(maximumSize);
184	    }
185	    if (maximumWeight != null) {
186	      builder.maximumWeight(maximumWeight);
187	    }
188	    if (concurrencyLevel != null) {
189	      builder.concurrencyLevel(concurrencyLevel);
190	    }
191	    if (keyStrength != null) {
192	      switch (keyStrength) {
193	        case WEAK:
194	          builder.weakKeys();
195	          break;
196	        case SOFT:
197	        case STRONG:
198	          throw new AssertionError();
199	      }
200	    }
201	    if (valueStrength != null) {
202	      switch (valueStrength) {
203	        case SOFT:
204	          builder.softValues();
205	          break;
206	        case WEAK:
207	          builder.weakValues();
208	          break;
209	        case STRONG:
210	          throw new AssertionError();
211	      }
212	    }
213	    if (recordStats != null && recordStats) {
214	      builder.recordStats();
215	    }
216	    if (writeExpirationTimeUnit != null) {
217	      builder.expireAfterWrite(writeExpirationDuration, writeExpirationTimeUnit);
218	    }
219	    if (accessExpirationTimeUnit != null) {
220	      builder.expireAfterAccess(accessExpirationDuration, accessExpirationTimeUnit);
221	    }
222	    if (refreshTimeUnit != null) {
223	      builder.refreshAfterWrite(refreshDuration, refreshTimeUnit);
224	    }
225	
226	    return builder;
227	  }
