238	  /**
239	   * Returns a string representation for this CacheBuilderSpec instance. The form of this
240	   * representation is not guaranteed.
241	   */
242	  @Override
243	  public String toString() {
244	    return MoreObjects.toStringHelper(this).addValue(toParsableString()).toString();
245	  }
246	
247	  @Override
248	  public int hashCode() {
249	    return Objects.hash(
250	        initialCapacity,
251	        maximumSize,
252	        maximumWeight,
253	        concurrencyLevel,
254	        keyStrength,
255	        valueStrength,
256	        recordStats,
257	        durationInNanos(writeExpirationDuration, writeExpirationTimeUnit),
258	        durationInNanos(accessExpirationDuration, accessExpirationTimeUnit),
259	        durationInNanos(refreshDuration, refreshTimeUnit));
260	  }
261	
262	  @Override
263	  public boolean equals(@Nullable Object obj) {
264	    if (this == obj) {
265	      return true;
266	    }
267	    if (!(obj instanceof CacheBuilderSpec)) {
268	      return false;
269	    }
270	    CacheBuilderSpec that = (CacheBuilderSpec) obj;
271	    return Objects.equals(initialCapacity, that.initialCapacity)
272	        && Objects.equals(maximumSize, that.maximumSize)
273	        && Objects.equals(maximumWeight, that.maximumWeight)
274	        && Objects.equals(concurrencyLevel, that.concurrencyLevel)
275	        && Objects.equals(keyStrength, that.keyStrength)
276	        && Objects.equals(valueStrength, that.valueStrength)
277	        && Objects.equals(recordStats, that.recordStats)
278	        && Objects.equals(
279	            durationInNanos(writeExpirationDuration, writeExpirationTimeUnit),
280	            durationInNanos(that.writeExpirationDuration, that.writeExpirationTimeUnit))
281	        && Objects.equals(
282	            durationInNanos(accessExpirationDuration, accessExpirationTimeUnit),
283	            durationInNanos(that.accessExpirationDuration, that.accessExpirationTimeUnit))
284	        && Objects.equals(
285	            durationInNanos(refreshDuration, refreshTimeUnit),
286	            durationInNanos(that.refreshDuration, that.refreshTimeUnit));
287	  }
