289	  /**
290	   * Converts an expiration duration/unit pair into a single Long for hashing and equality. Uses
291	   * nanos to match CacheBuilder implementation.
292	   */
293	  private static @Nullable Long durationInNanos(long duration, @Nullable TimeUnit unit) {
294	    return (unit == null) ? null : unit.toNanos(duration);
295	  }
