297	  /** Base class for parsing integers. */
298	  private abstract static class IntegerParser implements ValueParser {
299	    abstract void writeToSpec(CacheBuilderSpec spec, int value);
300	
301	    @Override
302	    public void parse(CacheBuilderSpec spec, String key, @Nullable String value) {
303	      if (isNullOrEmpty(value)) {
304	        throw new IllegalArgumentException("value of key " + key + " omitted");
305	      }
306	      try {
307	        writeToSpec(spec, parseInt(value));
308	      } catch (NumberFormatException e) {
309	        throw new IllegalArgumentException(
310	            format("key %s value set to %s, must be integer", key, value), e);
311	      }
312	    }
313	  }
314	
315	  /** Base class for parsing integers. */
316	  private abstract static class LongParser implements ValueParser {
317	    abstract void writeToSpec(CacheBuilderSpec spec, long value);
318	
319	    @Override
320	    public void parse(CacheBuilderSpec spec, String key, @Nullable String value) {
321	      if (isNullOrEmpty(value)) {
322	        throw new IllegalArgumentException("value of key " + key + " omitted");
323	      }
324	      try {
325	        writeToSpec(spec, parseLong(value));
326	      } catch (NumberFormatException e) {
327	        throw new IllegalArgumentException(
328	            format("key %s value set to %s, must be integer", key, value), e);
329	      }
330	    }
331	  }
332	
333	  /** Parse initialCapacity */
334	  private static final class InitialCapacityParser extends IntegerParser {
335	    @Override
336	    void writeToSpec(CacheBuilderSpec spec, int value) {
337	      checkArgument(
338	          spec.initialCapacity == null,
339	          "initial capacity was already set to %s",
340	          spec.initialCapacity);
341	      spec.initialCapacity = value;
342	    }
343	  }
344	
345	  /** Parse maximumSize */
346	  private static final class MaximumSizeParser extends LongParser {
347	    @Override
348	    void writeToSpec(CacheBuilderSpec spec, long value) {
349	      checkArgument(
350	          spec.maximumSize == null, "maximum size was already set to %s", spec.maximumSize);
351	      checkArgument(
352	          spec.maximumWeight == null, "maximum weight was already set to %s", spec.maximumWeight);
353	      spec.maximumSize = value;
354	    }
355	  }
356	
357	  /** Parse maximumWeight */
358	  private static final class MaximumWeightParser extends LongParser {
359	    @Override
360	    void writeToSpec(CacheBuilderSpec spec, long value) {
361	      checkArgument(
362	          spec.maximumWeight == null, "maximum weight was already set to %s", spec.maximumWeight);
363	      checkArgument(
364	          spec.maximumSize == null, "maximum size was already set to %s", spec.maximumSize);
365	      spec.maximumWeight = value;
366	    }
367	  }
368	
369	  /** Parse concurrencyLevel */
370	  private static final class ConcurrencyLevelParser extends IntegerParser {
371	    @Override
372	    void writeToSpec(CacheBuilderSpec spec, int value) {
373	      checkArgument(
374	          spec.concurrencyLevel == null,
375	          "concurrency level was already set to %s",
376	          spec.concurrencyLevel);
377	      spec.concurrencyLevel = value;
378	    }
379	  }
380	
381	  /** Parse weakKeys */
382	  private static final class KeyStrengthParser implements ValueParser {
383	    private final Strength strength;
384	
385	    KeyStrengthParser(Strength strength) {
386	      this.strength = strength;
387	    }
388	
389	    @Override
390	    public void parse(CacheBuilderSpec spec, String key, @Nullable String value) {
391	      checkArgument(value == null, "key %s does not take values", key);
392	      checkArgument(spec.keyStrength == null, "%s was already set to %s", key, spec.keyStrength);
393	      spec.keyStrength = strength;
394	    }
395	  }
396	
397	  /** Parse weakValues and softValues */
398	  private static final class ValueStrengthParser implements ValueParser {
399	    private final Strength strength;
400	
401	    ValueStrengthParser(Strength strength) {
402	      this.strength = strength;
403	    }
404	
405	    @Override
406	    public void parse(CacheBuilderSpec spec, String key, @Nullable String value) {
407	      checkArgument(value == null, "key %s does not take values", key);
408	      checkArgument(
409	          spec.valueStrength == null, "%s was already set to %s", key, spec.valueStrength);
410	
411	      spec.valueStrength = strength;
412	    }
413	  }
414	
415	  /** Parse recordStats */
416	  private static final class RecordStatsParser implements ValueParser {
417	
418	    @Override
419	    public void parse(CacheBuilderSpec spec, String key, @Nullable String value) {
420	      checkArgument(value == null, "recordStats does not take values");
421	      checkArgument(spec.recordStats == null, "recordStats already set");
422	      spec.recordStats = true;
423	    }
424	  }
425	
426	  /** Base class for parsing times with durations */
427	  private abstract static class DurationParser implements ValueParser {
428	    abstract void writeToSpec(CacheBuilderSpec spec, long duration, TimeUnit unit);
429	
430	    @Override
431	    public void parse(CacheBuilderSpec spec, String key, @Nullable String value) {
432	      if (isNullOrEmpty(value)) {
433	        throw new IllegalArgumentException("value of key " + key + " omitted");
434	      }
435	      try {
436	        char lastChar = value.charAt(value.length() - 1);
437	        TimeUnit timeUnit;
438	        switch (lastChar) {
439	          case 'd':
440	            timeUnit = DAYS;
441	            break;
442	          case 'h':
443	            timeUnit = HOURS;
444	            break;
445	          case 'm':
446	            timeUnit = MINUTES;
447	            break;
448	          case 's':
449	            timeUnit = SECONDS;
450	            break;
451	          default:
452	            throw new IllegalArgumentException(
453	                format("key %s invalid unit: was %s, must end with one of [dhms]", key, value));
454	        }
455	
456	        long duration = parseLong(value.substring(0, value.length() - 1));
457	        writeToSpec(spec, duration, timeUnit);
458	      } catch (NumberFormatException e) {
459	        throw new IllegalArgumentException(
460	            format("key %s value set to %s, must be integer", key, value));
461	      }
462	    }
463	  }
464	
465	  /** Parse expireAfterAccess */
466	  private static final class AccessDurationParser extends DurationParser {
467	    @Override
468	    void writeToSpec(CacheBuilderSpec spec, long duration, TimeUnit unit) {
469	      checkArgument(spec.accessExpirationTimeUnit == null, "expireAfterAccess already set");
470	      spec.accessExpirationDuration = duration;
471	      spec.accessExpirationTimeUnit = unit;
472	    }
473	  }
474	
475	  /** Parse expireAfterWrite */
476	  private static final class WriteDurationParser extends DurationParser {
477	    @Override
478	    void writeToSpec(CacheBuilderSpec spec, long duration, TimeUnit unit) {
479	      checkArgument(spec.writeExpirationTimeUnit == null, "expireAfterWrite already set");
480	      spec.writeExpirationDuration = duration;
481	      spec.writeExpirationTimeUnit = unit;
482	    }
483	  }
484	
485	  /** Parse refreshAfterWrite */
486	  private static final class RefreshDurationParser extends DurationParser {
487	    @Override
488	    void writeToSpec(CacheBuilderSpec spec, long duration, TimeUnit unit) {
489	      checkArgument(spec.refreshTimeUnit == null, "refreshAfterWrite already set");
490	      spec.refreshDuration = duration;
491	      spec.refreshTimeUnit = unit;
492	    }
493	  }
494	
495	  @FormatMethod
496	  private static String format(String format, Object... args) {
497	    return String.format(Locale.ROOT, format, args);
498	  }
499	}
